import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, field, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Валидации: пустые обязательные, «abc», минус #80ff63 #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await expect(page.getByText('כדי לחשב, חסר: מחיר רכישה, רווח חודשי לפני מס.')).toBeVisible();

      await fillInputs(page, SET1);
      await fillInputs(page, { purchasePrice: '', monthlyProfit: '' });
      await expect(page.getByText('יש להזין מחיר רכישה')).toBeVisible();
      await expect(page.getByText('יש להזין רווח חודשי לפני מס')).toBeVisible();
      await expect(page.getByText(/^כדי לחשב, חסר:/)).toBeVisible();
      await expect(field(page, 'purchasePrice')).toHaveAttribute('aria-invalid', 'true');

      await fillInputs(page, { purchasePrice: 'abc' });
      await expect(page.getByText('יש להזין מספר בלבד')).toBeVisible();
      await expect(field(page, 'purchasePrice')).toHaveAttribute('aria-invalid', 'true');

      await fillInputs(page, { purchasePrice: '-5' });
      await expect(page.getByText('הסכום לא יכול להיות שלילי')).toBeVisible();
    });
  }
});
